INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-order-flow-amt-auction', 'order-flow-amt-auction', 'AMT auction rules on SPY and QQQ: failed auction and acceptance (order flow not yet tested; modelled options)', 'AMT auction rules with modelled option fills. Levels: the prior regular session''s value area from 5-minute bars (70% of volume, bin 0.02 x ATR14). Rule A, failed auction: a probe beyond the prior value area, then 2 closes back inside; trade toward the prior POC, stop one cent beyond the probe extreme. Rule C, acceptance: 6 closes beyond value with the session POC beyond it; target one value-area width beyond the edge, stop back inside value. Signals 09:35 to 15:00 New York, entry at the next 5-minute open, exit at stop, target or 15:45. Option form: same-day debit vertical, short strike at the target. Data: SPY and QQQ 5-minute bars, 4,754 sessions from 2007-10-22 to 2026-11-06. Vertex test (2026-11-16): Rule A no edge: 1,839 out-of-sample trades, net $-39,296 after costs, deflated Sharpe 0.000 (bar 0.95, N = 4); 0DTE form out-of-sample net $-83,950. Rule C no edge: 2,564 out-of-sample trades, net $-84,218, deflated Sharpe 0.000; 0DTE form net $-93,007. NautilusTrader replay: all 10,975 trades the same. Order flow (true delta) is not tested: it has about one week of sampled history; follow-up card vertex-orderflow-delta-filter. Research only.', 'python', 'backtested', 'docs/specs/strategies/order-flow-amt-auction.md', '["research-only","amt","intraday","spy","qqq","debit-vertical","failed"]'::jsonb, 'Entry timing', '[]'::jsonb)
